//! Source-bound Inventory projection from a disposable synthetic Count source.
#[path = "../../support/inventory/consumption-facts.rs"]
#[allow(dead_code)] mod facts;
#[path = "../../support/rust-postgres.rs"] mod fixture;
use erpx_server_inventory::public::{service_count_generic_detail::*,service_initial_physical_count::*};
use erpx_server_runtime::public::postgres::{PgTransactionError,PgUnitOfWork,TransactionOptions};
use erpx_server_shared::public::BusinessError;

#[tokio::test]
async fn facts_are_scoped_and_capture_current_stock_and_lot_balances() {
 fixture::with_database(2,|pool|async move{
  facts::setup(&pool,"none").await;
  sqlx::query("DELETE FROM commerce_stock WHERE warehouse_id='warehouse' AND product_id='product'").execute(pool.raw()).await.unwrap();
  sqlx::query("INSERT INTO finance_accounts(id,company_id,chart_id,code,name,category,currency,created_at,updated_at) VALUES('variance','company','chart','5400','Variance','expense','THB',0,0)").execute(pool.raw()).await.unwrap();
  let result=PgUnitOfWork::new(pool.clone()).run::<(),BusinessError,_>(TransactionOptions::default(),|c|Box::pin(async move{
   lock_initial_count_inventory_sources(c).await?;
   sqlx::query("INSERT INTO command_receipts(command_id,operation,actor_id,request_hash,record_id,result_json,created_at,authority_json) VALUES('setup','fixture.setup','maker','hash','company','{}',0,'{\"companyId\":\"company\"}'),('cmd','inventory.count.create','maker','hash','count-cmd','{\"id\":\"count-cmd\",\"status\":\"draft\",\"version\":1,\"_serviceInitialPhysicalStockCount\":{}}',0,'{\"companyId\":\"company\"}')").execute(&mut *c).await?;
   let history=read_initial_count_inventory_history(c,"warehouse","product",None).await?;
   let draft=InitialCountDraft{proof:InitialCountSourceProof{count_id:"count-cmd".into(),selection:InitialCountSelection{company_id:"company".into(),branch_id:"branch".into(),warehouse_id:"warehouse".into(),product_id:"product".into(),count_date:"2026-01-10".into()},count_command_id:"cmd".into(),service_setup_command_id:"setup".into(),service_setup_request_hash:"hash".into(),finance:InitialCountFinanceBasis{chart_id:"chart".into(),inventory_account_id:"inventory".into(),variance_account_id:"variance".into(),currency:"THB".into()}},product:InitialCountProductSnapshot{version:1,description:"Product".into(),unit:"piece".into(),tracking:TrackingMode::Lot},reason:"Actual count".into(),actor_id:"maker".into(),value:value_initial_count(TrackingMode::Lot,0,None,vec![]).unwrap(),created_at:1};
   insert_initial_count_draft(c,&draft,&history).await?;
   let empty_source=read_initial_count_record(c,"company",Some("branch"),"count-cmd").await?.unwrap();
   let empty=read_service_count_generic_facts(c,&empty_source).await?;
   assert!(empty["lines"][0]["current_quantity_milli"].is_null());assert!(empty["lines"][0]["current_value_minor"].is_null());assert_eq!(empty["lines"][0]["current_version"],0);
   sqlx::raw_sql("INSERT INTO commerce_stock(warehouse_id,product_id,quantity_milli,value_minor) VALUES('warehouse','product',2000,400); INSERT INTO inventory_lots(id,company_id,product_id,tracking_mode,lot_code,created_by,created_at) VALUES('lot','company','product','lot','A','maker',1); INSERT INTO inventory_lot_balances(lot_id,warehouse_id,quantity_milli,value_minor) VALUES('lot','warehouse',2000,400); INSERT INTO inventory_count_lot_lines(id,count_line_id,result_lot_id,tracking_mode,lot_code,snapshot_quantity_milli,snapshot_value_minor,snapshot_version,counted_quantity_milli,counted_value_minor) VALUES('line-lot','count-cmd-0','lot','lot','A',0,0,0,0,0)").execute(&mut *c).await?;
   let source=read_initial_count_record(c,"company",Some("branch"),"count-cmd").await?.unwrap();
   let value=read_service_count_generic_facts(c,&source).await?;
   assert_eq!(value["count"]["id"],"count-cmd");assert_eq!(value["lines"][0]["current_quantity_milli"],2000);assert_eq!(value["lines"][0]["current_value_minor"],400);assert_eq!(value["lotLines"][0]["current_quantity_milli"],2000);assert_eq!(value["lotLines"][0]["current_value_minor"],400);assert_eq!(value["decisions"],serde_json::json!([]));
   sqlx::query("UPDATE inventory_counts SET reason='changed' WHERE id='count-cmd'").execute(&mut *c).await?;assert!(read_service_count_generic_facts(c,&source).await.is_err());
   Err(BusinessError::invalid("ROLLBACK_FIXTURE","Rollback synthetic receipt").into())
  })).await;
  assert!(matches!(result,Err(PgTransactionError::Business(e)) if e.code=="ROLLBACK_FIXTURE"));
 }).await;
}

#[tokio::test]
async fn quality_lineage_count_cte_matches_actual_typescript_recursive_sql() {
 use erpx_server_inventory::public::quality_lineage_counts::{inspect_quality_lineage_counts,lock_quality_lineage_counts};
 let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");let source=root.join("packages/server-quality/src/adapters/purchase-sources.ts");
 let script=r#"if(Bun.version!=='1.4.3')throw Error('PINNED_BUN_REQUIRED');const q=await import(process.argv[1]);const x=q.qualityPurchaseSourceRows;const end=x.indexOf('), roots AS');if(end<0||!x.startsWith('WITH RECURSIVE lineage AS (')||!x.includes('JOIN inventory_counts c ON'))throw Error('SOURCE_CHANGED');const fn=q.qualityHoldPurchaseSource.toString(),start=fn.indexOf('WITH RECURSIVE lineage AS ('),finish=fn.indexOf('ORDER BY depth DESC LIMIT 1',start);if(start<0||finish<0)throw Error('SELECTED_SOURCE_CHANGED');process.stdout.write(JSON.stringify({global:x.slice(0,end)+') SELECT hold_id,root_id,depth FROM lineage ORDER BY hold_id,depth',selected:fn.slice(start,finish)+'ORDER BY depth DESC LIMIT 1'}));"#;
 let oracle=std::process::Command::new(std::env::var("ERPX_BUN_BIN").expect("pinned Bun required")).current_dir(root).args(["--conditions=react-server","-e",script]).arg(source).output().unwrap();assert!(oracle.status.success(),"TS source oracle: {}",String::from_utf8_lossy(&oracle.stderr));let queries:serde_json::Value=serde_json::from_slice(&oracle.stdout).unwrap();let original=queries["global"].as_str().unwrap().to_owned();let selected=queries["selected"].as_str().unwrap().to_owned();
 fixture::with_database(2,|pool|async move{
  facts::setup(&pool,"none").await;
  sqlx::raw_sql("INSERT INTO inventory_quality_holds(id,company_id,branch_id,warehouse_id,product_id,reason,due_date,status,created_by,created_at,updated_at,quantity_scope,held_quantity_milli,source_type,source_id) VALUES('root','company','branch','warehouse','product','Review','2026-11-10','held','maker',0,0,'partial',3000,'goods_receipt','origin'); INSERT INTO inventory_counts(id,company_id,branch_id,warehouse_id,number,count_date,reason,status,quality_hold_id,created_by,prepared_by,created_at,updated_at) VALUES('count-1','company','branch','warehouse','C1','2026-11-10','Scrap','posted','root','maker','maker',0,0); UPDATE inventory_quality_holds SET status='disposed',last_result='fail',disposition_kind='scrap',disposition_reason='Scrap',disposition_requested_by='reviewer',disposition_count_id='count-1',disposition_quantity_milli=1000,disposed_by='approver',disposed_at=1 WHERE id='root'; INSERT INTO inventory_quality_disposition_events(id,hold_id,count_id,action,actor_id,reviewed_version,reason,created_at) VALUES('event-1','root','count-1','post','approver',1,'Scrap',1); INSERT INTO inventory_quality_holds(id,company_id,branch_id,warehouse_id,product_id,reason,due_date,status,created_by,created_at,updated_at,quantity_scope,held_quantity_milli,source_type,source_id) VALUES('root-remaining-count-1','company','branch','warehouse','product','Remaining','2026-11-10','held','maker',1,1,'partial',2000,'goods_receipt','origin:remaining:count-1')").execute(pool.raw()).await.unwrap();
  sqlx::raw_sql("INSERT INTO inventory_counts(id,company_id,branch_id,warehouse_id,number,count_date,reason,status,quality_hold_id,created_by,prepared_by,created_at,updated_at) VALUES('count-2','company','branch','warehouse','C-multi','2026-11-10','Scrap','posted','root-remaining-count-1','maker','maker',0,0); UPDATE inventory_quality_holds SET status='disposed',last_result='fail',disposition_kind='scrap',disposition_reason='Scrap',disposition_requested_by='reviewer',disposition_count_id='count-2',disposition_quantity_milli=500,disposed_by='approver',disposed_at=2 WHERE id='root-remaining-count-1'; INSERT INTO inventory_quality_disposition_events(id,hold_id,count_id,action,actor_id,reviewed_version,reason,created_at) VALUES('event-2','root-remaining-count-1','count-2','post','approver',1,'Scrap',2); INSERT INTO inventory_quality_holds(id,company_id,branch_id,warehouse_id,product_id,reason,due_date,status,created_by,created_at,updated_at,quantity_scope,held_quantity_milli,source_type,source_id) VALUES('root-remaining-count-1-remaining-count-2','company','branch','warehouse','product','Remaining','2026-11-10','held','maker',2,2,'partial',1500,'goods_receipt','origin:remaining:count-1:remaining:count-2')").execute(pool.raw()).await.unwrap();
  // The Count exists and is posted, but belongs to a different hold.
  sqlx::raw_sql("INSERT INTO inventory_quality_holds(id,company_id,branch_id,warehouse_id,product_id,reason,due_date,status,created_by,created_at,updated_at,quantity_scope,held_quantity_milli,source_type,source_id) VALUES('wrong','company','branch','warehouse','product','Review','2026-11-10','held','maker',0,0,'partial',3000,'goods_receipt','wrong-origin'); UPDATE inventory_quality_holds SET status='disposed',last_result='fail',disposition_kind='scrap',disposition_reason='Scrap',disposition_requested_by='reviewer',disposition_count_id='count-1',disposition_quantity_milli=1000,disposed_by='approver',disposed_at=1 WHERE id='wrong'; INSERT INTO inventory_quality_disposition_events(id,hold_id,count_id,action,actor_id,reviewed_version,reason,created_at) VALUES('event-wrong','wrong','count-1','post','approver',1,'Scrap',1); INSERT INTO inventory_quality_holds(id,company_id,branch_id,warehouse_id,product_id,reason,due_date,status,created_by,created_at,updated_at,quantity_scope,held_quantity_milli,source_type,source_id) VALUES('wrong-remaining-count-1','company','branch','warehouse','product','Remaining','2026-11-10','held','maker',1,1,'partial',2000,'goods_receipt','wrong-origin:remaining:count-1')").execute(pool.raw()).await.unwrap();
  let mut tx=pool.raw().begin().await.unwrap();sqlx::query("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE").execute(&mut *tx).await.unwrap();assert!(inspect_quality_lineage_counts(&mut tx).await.is_err());lock_quality_lineage_counts(&mut tx).await.unwrap();let witness=inspect_quality_lineage_counts(&mut tx).await.unwrap();
  assert_eq!(original.matches("JOIN inventory_counts c ON").count(),1);
  let projected=original.replacen("WITH RECURSIVE lineage AS (",&format!("WITH RECURSIVE {}, lineage AS (",witness.cte_sql()),1).replacen("JOIN inventory_counts c ON","JOIN quality_lineage_counts c ON",1);
  let actual:Vec<(String,String,i32)>=sqlx::query_as(sqlx::AssertSqlSafe(projected.as_str())).fetch_all(&mut *tx).await.unwrap();let expected:Vec<(String,String,i32)>=sqlx::query_as(sqlx::AssertSqlSafe(original.as_str())).fetch_all(&mut *tx).await.unwrap();assert_eq!(actual,expected);assert!(actual.contains(&("root-remaining-count-1".into(),"root".into(),1)));assert!(actual.contains(&("root-remaining-count-1-remaining-count-2".into(),"root".into(),2)));assert!(!actual.contains(&("wrong-remaining-count-1".into(),"wrong".into(),1)));
  assert_eq!(selected.matches("JOIN inventory_counts c ON").count(),1);let selected_original=selected.replacen("h.id=? AND h.company_id=?","h.id=$1 AND h.company_id=$2",1);let selected_projected=selected_original.replacen("WITH RECURSIVE lineage AS (",&format!("WITH RECURSIVE {}, lineage AS (",witness.cte_sql()),1).replacen("JOIN inventory_counts c ON","JOIN quality_lineage_counts c ON",1);
  for (id,company) in [("root-remaining-count-1-remaining-count-2","company"),("root-remaining-count-1-remaining-count-2","foreign"),("missing","company")] {let base:Option<serde_json::Value>=sqlx::query_scalar(sqlx::AssertSqlSafe(format!("SELECT to_jsonb(q) FROM ({selected_original}) q"))).bind(id).bind(company).fetch_optional(&mut *tx).await.unwrap();let actual:Option<serde_json::Value>=sqlx::query_scalar(sqlx::AssertSqlSafe(format!("SELECT to_jsonb(q) FROM ({selected_projected}) q"))).bind(id).bind(company).fetch_optional(&mut *tx).await.unwrap();assert_eq!(actual,base);if company=="company"&&id.starts_with("root-"){assert_eq!(actual.unwrap()["id"],"root");}else{assert!(actual.is_none());}}
  sqlx::query("SAVEPOINT add_count").execute(&mut *tx).await.unwrap();sqlx::query("INSERT INTO inventory_counts(id,company_id,branch_id,warehouse_id,number,count_date,reason,status,created_by,prepared_by,created_at,updated_at) VALUES('other-count','company','branch','warehouse','C2','2026-11-11','Independent count','draft','maker','maker',0,0)").execute(&mut *tx).await.unwrap();let changed:Vec<(String,String,i32)>=sqlx::query_as(sqlx::AssertSqlSafe(projected.as_str())).fetch_all(&mut *tx).await.unwrap();let changed_original:Vec<(String,String,i32)>=sqlx::query_as(sqlx::AssertSqlSafe(original.as_str())).fetch_all(&mut *tx).await.unwrap();assert_eq!(changed,changed_original);assert_eq!(changed,actual);witness.require_current(&mut tx).await.unwrap();sqlx::query("ROLLBACK TO SAVEPOINT add_count").execute(&mut *tx).await.unwrap();tx.rollback().await.unwrap();
  let mut fresh=pool.raw().begin().await.unwrap();sqlx::query("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE").execute(&mut *fresh).await.unwrap();lock_quality_lineage_counts(&mut fresh).await.unwrap();assert!(witness.require_current(&mut fresh).await.is_err());fresh.rollback().await.unwrap();
  let mut saved=pool.raw().begin().await.unwrap();sqlx::query("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE").execute(&mut *saved).await.unwrap();sqlx::query("SELECT pg_current_xact_id()").execute(&mut *saved).await.unwrap();sqlx::query("SAVEPOINT before_count_lock").execute(&mut *saved).await.unwrap();lock_quality_lineage_counts(&mut saved).await.unwrap();let held=inspect_quality_lineage_counts(&mut saved).await.unwrap();sqlx::query("ROLLBACK TO SAVEPOINT before_count_lock").execute(&mut *saved).await.unwrap();assert!(held.require_current(&mut saved).await.is_err());saved.rollback().await.unwrap();
 }).await;
}

#[tokio::test]
async fn quality_lineage_count_fence_rejects_shadow_rls_and_excess_sources() {
 use erpx_server_inventory::public::quality_lineage_counts::{inspect_quality_lineage_counts,lock_quality_lineage_counts};
 fixture::with_database(2,|pool|async move{
  facts::setup(&pool,"none").await;
  let mut tx=pool.raw().begin().await.unwrap();sqlx::query("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE").execute(&mut *tx).await.unwrap();lock_quality_lineage_counts(&mut tx).await.unwrap();let witness=inspect_quality_lineage_counts(&mut tx).await.unwrap();
  let reader_pid:i32=sqlx::query_scalar("SELECT pg_backend_pid()").fetch_one(&mut *tx).await.unwrap();let(send,receive)=tokio::sync::oneshot::channel();let writer_pool=pool.clone();let writer=tokio::spawn(async move{let mut w=writer_pool.raw().begin().await.unwrap();sqlx::query("SET LOCAL lock_timeout='3s'").execute(&mut *w).await.unwrap();let pid:i32=sqlx::query_scalar("SELECT pg_backend_pid()").fetch_one(&mut *w).await.unwrap();send.send(pid).unwrap();let e=sqlx::query("INSERT INTO public.inventory_counts(id,company_id,branch_id,warehouse_id,number,count_date,reason,created_by,prepared_by,created_at,updated_at) VALUES('blocked','company','branch','warehouse','blocked','2026-11-10','Count','maker','maker',0,0)").execute(&mut *w).await.unwrap_err();assert_eq!(e.as_database_error().and_then(|x|x.code()).as_deref(),Some("55P03"));w.rollback().await.unwrap();});let pid=receive.await.unwrap();tokio::time::timeout(std::time::Duration::from_secs(2),async{loop{let waiting:bool=sqlx::query_scalar("SELECT $1=ANY(pg_blocking_pids($2)) AND EXISTS(SELECT 1 FROM pg_locks WHERE pid=$2 AND relation='public.inventory_counts'::regclass AND mode='RowExclusiveLock' AND NOT granted)").bind(reader_pid).bind(pid).fetch_one(&mut *tx).await.unwrap();if waiting{break}tokio::task::yield_now().await;}}).await.expect("writer must wait for exact Count table lock");writer.await.unwrap();witness.require_current(&mut tx).await.unwrap();tx.rollback().await.unwrap();
  let mut shadow=pool.raw().begin().await.unwrap();sqlx::query("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE").execute(&mut *shadow).await.unwrap();sqlx::query("CREATE TEMP TABLE inventory_counts(id text)").execute(&mut *shadow).await.unwrap();lock_quality_lineage_counts(&mut shadow).await.unwrap();assert!(inspect_quality_lineage_counts(&mut shadow).await.is_err());shadow.rollback().await.unwrap();
  let mut rls=pool.raw().begin().await.unwrap();sqlx::query("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE").execute(&mut *rls).await.unwrap();let bypass:bool=sqlx::query_scalar("SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname=current_user").fetch_one(&mut *rls).await.unwrap();assert!(!bypass);sqlx::raw_sql("ALTER TABLE public.inventory_counts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inventory_counts FORCE ROW LEVEL SECURITY").execute(&mut *rls).await.unwrap();let active:bool=sqlx::query_scalar("SELECT row_security_active('public.inventory_counts'::regclass)").fetch_one(&mut *rls).await.unwrap();assert!(active);lock_quality_lineage_counts(&mut rls).await.unwrap();assert!(inspect_quality_lineage_counts(&mut rls).await.is_err());rls.rollback().await.unwrap();
  let mut bounded=pool.raw().begin().await.unwrap();sqlx::query("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE").execute(&mut *bounded).await.unwrap();lock_quality_lineage_counts(&mut bounded).await.unwrap();let empty=inspect_quality_lineage_counts(&mut bounded).await.unwrap();
  sqlx::query("SAVEPOINT bytes_bound").execute(&mut *bounded).await.unwrap();sqlx::query("INSERT INTO public.inventory_counts(id,company_id,branch_id,warehouse_id,number,count_date,reason,created_by,prepared_by,created_at,updated_at) SELECT repeat('x',1800)||n::text,'company','branch','warehouse','wide-'||n::text,'2026-11-10','Count','maker','maker',0,0 FROM generate_series(1,1200) n").execute(&mut *bounded).await.unwrap();let measured:(i64,i64)=sqlx::query_as("SELECT count(*)::bigint,COALESCE(sum(octet_length(to_jsonb(s)::text)::bigint),0)::bigint FROM (SELECT id,quality_hold_id,company_id,branch_id,warehouse_id,status FROM public.inventory_counts) s").fetch_one(&mut *bounded).await.unwrap();assert_eq!(measured.0,1200);assert!(measured.0<=10000 && measured.1>2097152,"byte-only excess: {measured:?}");let e=inspect_quality_lineage_counts(&mut bounded).await.err().expect("byte budget must reject oversized source");assert!(matches!(e,PgTransactionError::Business(ref e) if e.code=="QUALITY_LINEAGE_COUNT_LIMIT"));assert!(empty.require_current(&mut bounded).await.is_err());sqlx::query("ROLLBACK TO SAVEPOINT bytes_bound").execute(&mut *bounded).await.unwrap();empty.require_current(&mut bounded).await.unwrap();
  sqlx::query("INSERT INTO public.inventory_counts(id,company_id,branch_id,warehouse_id,number,count_date,reason,created_by,prepared_by,created_at,updated_at) SELECT 'count-'||n::text,'company','branch','warehouse','number-'||n::text,'2026-11-10','Count','maker','maker',0,0 FROM generate_series(1,10001) n").execute(&mut *bounded).await.unwrap();let measured:(i64,i64)=sqlx::query_as("SELECT count(*)::bigint,COALESCE(sum(octet_length(to_jsonb(s)::text)::bigint),0)::bigint FROM (SELECT id,quality_hold_id,company_id,branch_id,warehouse_id,status FROM public.inventory_counts) s").fetch_one(&mut *bounded).await.unwrap();assert_eq!(measured.0,10001);assert!(measured.1<=2097152,"row-only excess requires bytes within limit: {measured:?}");let e=inspect_quality_lineage_counts(&mut bounded).await.err().expect("row budget must reject oversized source");assert!(matches!(e,PgTransactionError::Business(ref e) if e.code=="QUALITY_LINEAGE_COUNT_LIMIT"));bounded.rollback().await.unwrap();
 }).await;
}
